// ---- pretty console rendering (PRETTY only; a pure function of its argument) ----
// ANSI helpers are null unless PRETTY, so colour is implicitly TTY-gated.
const A = PRETTY ? {
  dim: (s) => `\x1b[2m${s}\x1b[0m`, red: (s) => `\x1b[1;31m${s}\x1b[0m`,
  grn: (s) => `\x1b[1;32m${s}\x1b[0m`, ylw: (s) => `\x1b[1;33m${s}\x1b[0m`,
  cyn: (s) => `\x1b[1;36m${s}\x1b[0m`, bold: (s) => `\x1b[1m${s}\x1b[0m`,
} : null;
