  if (/^(RUN ENDED|FATAL)/.test(line)) return `\n${A.red('✗ ' + line)}`;
  if (/^INTERRUPTED/.test(line)) return `\n${A.ylw('◦ ' + line)}`;
  if (/^BLOCKED/.test(line)) return `\n${A.ylw('◦ ' + line)}`;
