    if (/^mkfs(\.|$)/.test(head) || head === 'mke2fs' || head === 'wipefs' || head === 'shred' || head === 'blkdiscard') return true;
    if (head === 'dd' && /(^|\s)of=\/dev\//i.test(seg)) return true;
    // Recursive chmod/chown loosening a root-ish path.
    if ((head === 'chmod' || head === 'chown') && /(^|\s)(-\w*R\w*|--recursive)(\s|$)/.test(seg) && args.some((a) => a === '/' || /^\/(?:etc|usr|bin|sbin|lib|lib64|boot|dev|sys|var|root|home)?\/?$/.test(a))) return true;
