    for (const [abs, orig] of fileOriginals) {
      const rel = path.relative(WORKDIR, abs);
      manifest.push({ path: rel, existed: orig !== null });
      if (orig !== null) {
        const dest = path.join(ck, 'files', rel);
        fs.mkdirSync(path.dirname(dest), { recursive: true });
        fs.writeFileSync(dest, orig);
      }
    }
    fs.writeFileSync(path.join(ck, 'manifest.json'), JSON.stringify({ at: new Date().toISOString(), task: checkpointLabel(taskText), files: manifest }, null, 1));
