  const ck = path.join(checkpointRoot(), dirs[dirs.length - 1]);
  let man; try { man = JSON.parse(fs.readFileSync(path.join(ck, 'manifest.json'), 'utf8')); } catch { return 'Rewind failed: newest checkpoint has no readable manifest.'; }
