  // sentinels are whole-string locales, NOT language codes — matching just
  // the leading two letters turned LANG=POSIX into "po" (Polish) and C.UTF-8
  // into "c". Test the raw value for the sentinels before extracting a lang.
  const raw = String(process.env.LC_ALL || process.env.LANG || '').trim();
  if (!raw || /^(C|POSIX)(\.|@|$)/i.test(raw)) return 'en-US,en;q=0.9';
  const m = raw.match(/^([a-z]{2})(?:[_-]([A-Z]{2}))?/i);
  if (!m) return 'en-US,en;q=0.9';
  const lang = m[1].toLowerCase(), region = m[2] ? `-${m[2].toUpperCase()}` : '';
