    if (hay.trim().length < 60 && !filesCreated.size) return false; // too little output to judge
    // ONE shared word is not "on mission". This accepted any single token hit,
    // and generic charter words made that vacuous: "The game . Start building
    // the game not a site" (Elden Ring, established two turns earlier) produced
    // neon-bounce.html, and the tripwire passed it — "game" overlaps. A rich
    // charter (6+ distinct tokens, which every referentially-enriched objective
    // has) now needs TWO distinct hits; a sparse one keeps the single-hit rule,
    // because demanding two of a three-word charter would flag honest work.
    const need = charterTokens.size >= 6 ? 2 : 1;
    let hits = 0;
    for (const tok of charterTokens) { if (hay.includes(tok) && ++hits >= need) return false; }
    return true;
