    if (ghosts.length) out.push(`⚠ Harness check: the identifier(s) ${ghosts.map((g) => '`' + g + '`').join(', ')} appear in no tool output — the claimed findings are unverified, treat them as fabricated until re-queried.`);
    const researchIssues = researchIntegrityIssues(text);
    if (researchIssues.unsupported.length) out.push(`⚠ Shopping evidence missing for ${researchIssues.unsupported.length} detail${researchIssues.unsupported.length === 1 ? '' : 's'}.`);
    if (researchIssues.duplicates.length) out.push(`⚠ Duplicate product listing${researchIssues.duplicates.length === 1 ? '' : 's'}: ${researchIssues.duplicates.join(', ')}.`);
